j:jelly.g2:evaluate:
var availableScopes = availableList();
function availableList() {
	var answer = [];
	var grProfile = new GlideRecord('oauth_entity_profile');
	grProfile.addQuery('oauth_entity', jelly.jvar_sysId);
	grProfile.addQuery('default', 'true');
	grProfile.query();
	if (grProfile.next()) {
		var grScopes = new GlideRecord('oauth_entity_scope');
		grScopes.addQuery('oauth_entity', grProfile.oauth_entity);
		grScopes.query();
		while(grScopes.next()) {
			if (grScopes.getValue('in_default_profile') == 0) {
				answer.push(GlideStringUtil.base64Encode(grScopes.getValue('name')) + ':' + GlideStringUtil.base64Encode(grScopes.sys_id));
			}
		}
  	}
  	return answer.join('^');
}
availableScopes;

var selectedScopes = selectedList();
function selectedList() {
	var answer = [];
	var grProfile = new GlideRecord('oauth_entity_profile');
	grProfile.addQuery('oauth_entity', jelly.jvar_sysId);
	grProfile.addQuery('default', 'true');
	grProfile.query();
	if (grProfile.next()) {
		var grScopes = new GlideRecord('oauth_entity_scope');
		grScopes.addQuery('oauth_entity', grProfile.oauth_entity);
		grScopes.query();
		while(grScopes.next()) {
			if (grScopes.getValue('in_default_profile') == 1) {
				answer.push(GlideStringUtil.base64Encode(grScopes.getValue('name')) + ':' + GlideStringUtil.base64Encode(grScopes.sys_id));
			}
		}
  	}
  	return answer.join('^');
}
selectedScopes;
